using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasIndex(p => p.Sku);

            // EF Core 9 breaking change #1: discriminator renamed from
            // "Discriminator" to "$type".  Our 500K existing documents and
            // direct SQL queries use the old name, so keep it.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 breaking change #2: id format changed from
            // "EntityType|Key" (e.g. "Product|123") to just the key value.
            // Existing documents use the old format, so preserve it.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonPropertyName("id")
                  .HasConversion<string>(
                      v => $"Product|{v}",
                      v => int.Parse(v.Replace("Product|", "")));
        });
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

