class CosmosQuery
{
    async Task FindProductsAsync(ProductContext ctx)
    {
        // Direct Cosmos SQL — safe because we kept "Discriminator" as the
        // discriminator property name in OnModelCreating (see ProductContext).
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        // EF Core 9 breaking change #3: synchronous LINQ APIs (ToList,
        // First, Single, etc.) were removed for the Cosmos provider.
        // All queries must use their async counterparts.
        var products = await ctx.Products
            .Where(p => p.Sku == "ABC")
            .ToListAsync();
    }
}

